      "topicId": "W2.1a",
      "title": "Project Management → SDLC Process Models → Introduction → What",
      "prompt": "The _____ is to start coding and keep fixing what breaks, with no explicit stages at all. That approach, sometimes called code-and-fix , has no overhead and works well enough for a small program written by one person over a short period. It stops working as the software and the team grow. There is no way to tell how far along the work is, and no way to divide it among several people without them colliding. There is also no record of the decisions already made, so changes become harder and more expensive.",
      "answer": "simplest way to build software",
      "passage": "The simplest way to build software is to start coding and keep fixing what breaks, with no explicit stages at all. That approach, sometimes called code-and-fix , has no overhead and works well enough for a small program written by one person over a short period. It stops working as the software and the team grow. There is no way to tell how far along the work is, and no way to divide it among several people without them colliding. There is also no record of the decisions already made, so changes become harder and more expensive.",
