      "prompt": "A _____ is a tool that lets you pause a running program, then inspect and control it from the inside, without modifying its code. You choose the lines where the program should stop. When execution reaches one of them, the program freezes mid-run and waits for you. You can then look at the current values of its variables, see the chain of method calls that led there, and let it continue one line at a time. Most IDEs, such as IntelliJ IDEA, come with a _____ built in. There are also standalone debuggers that you control by typing commands, such as GDB for C and C++, and jdb for Java .",
