      "prompt": "_____ automates the simplification of the failing case , systematically removing parts of the input and keeping whichever reduction still fails. It handles the cases where plain halving does not, at a cost: in the worst case it needs on the order of n² tests. It still needs two things from you: a reliable test for whether a reduction still fails, and reductions that leave the input valid — a config file whose required header must survive every reduction is exactly such a constraint. The wider point: a mechanical procedure can replace intuition for this step.",
      "answer": "Delta debugging",
      "passage": "Delta debugging automates the simplification of the failing case , systematically removing parts of the input and keeping whichever reduction still fails. It handles the cases where plain halving does not, at a cost: in the worst case it needs on the order of n² tests. It still needs two things from you: a reliable test for whether a reduction still fails, and reductions that leave the input valid — a config file whose required header must survive every reduction is exactly such a constraint. The wider point: a mechanical procedure can replace intuition for this step.",
      "source": "https://nus-cs2103-ay2627-s1.github.io/website/schedule/week6/topics.html#implementation-debugging-advanced",
      "optional": false
