      "title": "Implementation → Debugging → Advanced",
      "prompt": "_____ are worth knowing once the basics are comfortable. force step into enters library code that step into normally skips. reset frame (or drop frame ) pops the current call so you can re-enter a method you stepped past — but it restores only the execution point and local variables. Anything the method already did to fields, static state, files, or console output stays done, so it is not a way of going back in time.",
