      "title": "Project Management → SDLC Process Models → Introduction → Sequential models",
      "prompt": "A strict sequential model project moves only in the forward direction i.e., each stage is completed before starting the next. For example, once the requirements stage is over, there is no provision for revising the requirements later. _____ is often relaxed to let a stage send work back to the one before it, although doing so means redoing work that was already treated as finished.",
